def f(inputs: List[Tuple[int, List[Tuple[str, int, int, int]]]]):
    '''
    inputs: a list of tuples, where each tuple consists of:
        - an integer
        - a list of tuples, each containing a string and three integers
    '''
    result = []
    for n, teams in inputs:
        scores = {t: 0 for t in teams}
        for team in teams:
            for opponent in teams:
                if team[0] == opponent[0]:
                    continue
                if team[1] == opponent[1]:
                    scores[team[0]] += 1
                elif team[1] > opponent[1]:
                    scores[team[0]] += 3
        result.append(sorted(scores.items(), key=lambda x: x[1], reverse=True))
    return result
